@Service
@RequiredArgsConstructor
public class MemberService {
    private final MemberRepository memberRepository;

    public void 위험한_호출() {
        memberRepository.deleteAll();     // 다 지운다
        memberRepository.flush();         // 인프라 관심사가 샌다
    }
}

